<script setup lang="ts">
const finance = useFinance(); const filter = ref<'all' | 'expense' | 'income' | 'transfer'>('all'); const money = (value: number) => new Intl.NumberFormat('th-TH', { style: 'currency', currency: 'THB' }).format(value)
const activity = computed(() => [...finance.transactions.value.map(item => ({ ...item, kind: item.type, label: item.title, detail: `${item.category} · ${item.accountName ?? ''}` })), ...finance.transfers.value.map(item => ({ ...item, kind: 'transfer' as const, label: `${item.fromAccountName} → ${item.toAccountName}`, detail: 'Transfer between accounts', type: 'transfer' as const, category: 'Transfer' }))].filter(item => filter.value === 'all' || item.kind === filter.value).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()))
onMounted(() => finance.refresh().catch(() => undefined))
</script>
<template><main class="page"><div class="topline"><div><div class="eyebrow">Your ledger</div><h1 class="display">History.</h1></div><NuxtLink to="/transactions/new" class="button accent">+ Entry</NuxtLink></div><div class="toolbar"><button v-for="item in ['all','expense','income','transfer']" :key="item" class="pill" :class="{ active: filter === item }" @click="filter = item as typeof filter">{{ item }}</button></div><p v-if="finance.error.value" class="notice error">{{ finance.error.value }}</p><div v-if="activity.length" class="transaction-list"><NuxtLink v-for="item in activity" :key="`${item.kind}-${item.id}`" :to="item.kind === 'transfer' ? `/transfers/${item.id}` : `/transactions/${item.id}`" class="transaction"><div class="transaction-icon">{{ item.kind === 'transfer' ? '↔' : item.category.charAt(0) }}</div><div class="transaction-copy"><strong>{{ item.label }}</strong><small>{{ item.detail }} · {{ new Date(item.date).toLocaleDateString() }}</small></div><div class="amount" :class="{ positive: item.kind === 'income', neutral: item.kind === 'transfer' }">{{ item.kind === 'income' ? '+' : item.kind === 'expense' ? '−' : '' }}{{ money(item.amount) }}</div></NuxtLink></div><div v-else class="empty"><strong>No entries yet.</strong><p class="muted">Add income, an expense, or move money between accounts.</p></div></main></template>

